<nav class="module-tabs" aria-label="Presse"><a href="?view=website&amp;tab=press" <?= $pressView!=='recipients'?'aria-current="page"':'' ?>>Pressemitteilungen & Versand</a><a href="?view=website&amp;tab=press&amp;press_view=recipients" <?= $pressView==='recipients'?'aria-current="page"':'' ?>>Presseempfänger · <?= count($native['rows']) ?></a></nav>
<?php if($pressView==='recipients'): ?>
