<?php if($pressEditable):$start('press/draft-save',['id'=>$campaign['id']??0,'event_id'=>$pressDraft['event_id']??0],$campaign['version']??'');$field('press_subject','Betreff',$pressDraft['subject']??'','text',true); ?>
