<?php else: ?><p class="native-pre"><?= e($pressDraft['body']) ?></p><?php if(!$pressCanWrite): ?><h3>Gespeicherte Empfänger</h3><ul><?php foreach($campaign['recipients']??[] as $person): ?><li><?= e($person['name'].' · '.$person['email']) ?></li><?php endforeach ?></ul><?php endif;endif ?>
