<?php $start('press/campaign-send',['id'=>$campaign['id']],$campaign['version']); ?><label class="check"><input class="check" type="checkbox" name="fields[send_confirmed]" value="1" required>Ich habe diese gespeicherte Fassung und die aufgeführten Empfänger geprüft.</label><?php $button($native['mail_allowed']?'Gespeicherte Pressemitteilung versenden':'Versand auf diesem PC gesperrt',$native['mail_allowed']&&count($campaign['recipients'])>0&&trim($campaign['body'])!==''); ?></details><?php endif ?>
<?php if($campaign): ?><section class="card"><h2>Versandverlauf & Empfänger</h2><?php if(!$campaign['deliveries']): ?><p>Noch nicht versendet. Die ausgewählten Empfänger stehen im gespeicherten Entwurf.</p><?php else: ?><p>„Versendet“ bedeutet: Der Mailserver hat die Nachricht angenommen. Ein unbekanntes Ergebnis wird nicht automatisch wiederholt.</p><div class="table-scroll"><table class="table"><thead><tr><th>Empfänger / Medium</th><th>E-Mail</th><th>Status</th><th>Zeitpunkt</th></tr></thead><tbody><?php foreach($campaign['deliveries'] as $delivery): ?><tr><td><?= e($delivery['name'].' · '.$delivery['outlet']) ?></td><td><?= e($delivery['email']) ?></td><td><?= e($pressStates[$delivery['status']]??$delivery['status']) ?></td><td><?= e(!empty($delivery['sent_at'])?date('d.m.Y H:i',$delivery['sent_at']):(!empty($delivery['attempted_at'])?'Versuch '.date('d.m.Y H:i',$delivery['attempted_at']):'–')) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section><?php endif ?>
<?php return;endif; ?>
<?php if($pressCanWrite): ?><section class="card"><div class="section-heading"><h2>Pressemitteilung erstellen</h2><a class="btn btn-outline theme-secondary button secondary" href="?view=website&amp;tab=press&amp;press_new=1&amp;free=1">Freie Pressemitteilung</a></div>
<?php $start('press/prepare'); ?><label>Aus einer Veranstaltung<select class="form-control" name="fields[event_id]" required><option value="">Veranstaltung auswählen</option><?php foreach($native['events'] as $event): ?><option value="<?= (int)$event['id'] ?>"><?= e(($event['start_at']?date('d.m.Y',$event['start_at']).' · ':'').$event['title']) ?></option><?php endforeach ?></select></label><p>Die vorhandene Vereins-Pressevorlage übernimmt Datum, Ort und Beschreibung. Der Text kann anschließend bearbeitet werden.</p><?php $button('Veranstaltungsentwurf vorbereiten',count($native['events'])>0); ?></section><?php endif ?>
<section class="card"><h2>Mitteilungen & Versandstatus</h2><div class="table-scroll"><table class="table"><thead><tr><th>Betreff</th><th>Status</th><th>Empfänger</th><th>Zuletzt bearbeitet / Versand</th></tr></thead><tbody><?php foreach($native['campaigns'] as $row): ?><tr><td><a href="<?= e($link(['item'=>$row['id']])) ?>"><?= e($row['subject']) ?></a><br><small><?= $row['event_id']?'Veranstaltung':'Freie Mitteilung' ?></small></td><td><?= e($pressStates[$row['status']]??$row['status']) ?></td><td><?= $row['recipient_count'] ?> ausgewählt · <?= $row['sent_count'] ?> versendet<br><a href="<?= e($link(['item'=>$row['id']])) ?>">Empfänger und Verlauf</a></td><td><?= e(date('d.m.Y H:i',$row['sent_at']?:$row['updated_at'])) ?></td></tr><?php endforeach ?><?php if(!$native['campaigns']): ?><tr><td colspan="4">Noch keine gespeicherten Pressemitteilungen.</td></tr><?php endif ?></tbody></table></div></section>
<?php if($native['campaign_pages']>1): ?><nav class="pagination" aria-label="Pressemitteilungen durchblättern"><?php if($native['campaign_page']>1): ?><a class="btn btn-outline theme-secondary button secondary" href="<?= e($link(['page'=>$native['campaign_page']-1])) ?>">← Zurück</a><?php endif ?><span>Seite <?= $native['campaign_page'] ?> von <?= $native['campaign_pages'] ?></span><?php if($native['campaign_page']<$native['campaign_pages']): ?><a class="btn btn-outline theme-secondary button secondary" href="<?= e($link(['page'=>$native['campaign_page']+1])) ?>">Weiter →</a><?php endif ?></nav><?php endif ?>
<?php $legacy=array_filter($native['events'],fn($event)=>!empty($event['sent_at']));if($legacy): ?><details class="card"><summary>Bisherige Versandvermerke · <?= count($legacy) ?></summary><p>Ältere Vermerke enthalten teilweise keine Empfängerliste. Diese Angaben werden nicht nachträglich aus dem heutigen Verteiler abgeleitet.</p><?php foreach($legacy as $event): ?><article><h3><?= e($event['title']) ?></h3><p><?= e(date('d.m.Y H:i',$event['sent_at'])) ?> · <?= $event['delivery']==='smtp-bcc'?'Als versendet protokolliert':'Manuell als versendet markiert' ?><?= $event['recipient_count']?' · '.$event['recipient_count'].' Empfänger':'' ?></p><?php if($event['recipients']): ?><ul><?php foreach($event['recipients'] as $person): ?><li><?= e(($person['name']??'').' · '.($person['email']??'')) ?></li><?php endforeach ?></ul><?php else: ?><p>Empfänger damals nicht gespeichert.</p><?php endif ?></article><?php endforeach ?></details><?php endif ?>
